def verify_isbn(isbn: str) -> str:
    if len(isbn) != 13 or not isbn[12].isdigit() and isbn[12] != 'X':
        return "Invalid ISBN format"

    # Calculate the checksum
    sum = 0
    for i in range(12):
        if i % 2 == 0:
            sum += int(isbn[i])
        else:
            sum += int(isbn[i]) * 3

    # Check if the checksum is correct
    if sum % 10 == 0:
        return "Right"
    else:
        # Calculate the correct checksum digit
        correct_digit = 10 - (sum % 10)
        if correct_digit == 10:
            correct_digit = 'X'
        return isbn[:12] + correct_digit

